package com.nametag.api;
import com.nametag.domain.match.model.*; import com.nametag.domain.settle.model.*; import com.nametag.domain.evaluate.model.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/v1") public class ApiController {private final NametagService service; public ApiController(NametagService s){service=s;} @GetMapping("/health")ApiResponse<?> health(){return ApiResponse.ok(Map.of("fixture",true,"animals",service.animals().size()));} @GetMapping("/regions/sido")ApiResponse<?> sido(){return ApiResponse.ok(List.of(Map.of("uprCd","6110000","orgdownNm","서울"),Map.of("uprCd","6410000","orgdownNm","경기")));} @GetMapping("/regions/sigungu")ApiResponse<?> sigungu(@RequestParam String uprCd){return ApiResponse.ok(List.of(Map.of("orgCd",uprCd+"001","orgdownNm","강남구")));} @PostMapping("/matches")ApiResponse<MatchOutput> match(@RequestBody Profile p){return ApiResponse.ok(service.match(p));} @PostMapping("/settle-plans")ApiResponse<SettlePlan> settle(@RequestBody Profile p){return ApiResponse.ok(service.settle(p));} @GetMapping("/evaluations")ApiResponse<Evaluation> evaluate(){return ApiResponse.ok(service.evaluate());}}
